mapper.select:
SELECT

FROM mes_maintenance_record
WHERE 1=1

    AND maintenance_no LIKE CONCAT('%', #{query.maintenanceNo}, '%')


    AND equipment_id = #{query.equipmentId}


    AND record_type = #{query.recordType}


    AND sub_type = #{query.subType}


    AND status = #{query.status}


    AND maintainer LIKE CONCAT('%', #{query.maintainer}, '%')


    AND create_time >= #{query.startTime}


    AND create_time <= #{query.endTime}


    AND result = #{query.result}

ORDER BY


        ${query.sortField} ${query.sortOrder}


        create_time DESC

mapper.update:
UPDATE mes_maintenance_record
SET
    status = #{status},
    update_time = #{updateTime}
WHERE record_id = #{recordId}
